const AVATARS = {
  "Михаил Соколов": "mikhail", "Анна Смирнова": "anna", "Александр Волков": "alexander",
  "Иван Михайлов": "ivan", "Ольга Смирнова": "olga", "Дмитрий Ким": "dmitry",
};
const heroImage = (id) => `/public/images/heroes/${id}-dark.webp`;
const initials = (name) => name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();
const entityProfilePath = (name) => name === "Детейлинг Партнёр" ? "/profile/partner-001" : `/companies/${name === "АвтоПрофи" ? "company-003" : name === "CleanLab" ? "company-002" : "company-001"}`;

function personAvatar(name, cls = "") {
  const file = AVATARS[name];
  return `<span class="avatar ${cls} ${file ? "photo-avatar" : ""}" aria-hidden="true">${file ? `<img src="/public/images/avatars/${file}.jpg" alt="">` : esc(initials(name))}</span>`;
}

function brandAvatar(name, cls = "") {
  return `<span class="brand-avatar ${cls}" aria-hidden="true">${esc(initials(name))}</span>`;
}

function panel(title, body, { actions = "", eyebrow = "", cls = "" } = {}) {
  return `<section class="workspace-panel ${cls}"><header class="workspace-panel-head"><div>${eyebrow ? `<span class="workspace-kicker">${eyebrow}</span>` : ""}<h2>${title}</h2></div>${actions ? `<div class="workspace-panel-actions">${actions}</div>` : ""}</header>${body}</section>`;
}

function progress(value, label = "") {
  return `<div class="workspace-progress" ${label ? `aria-label="${esc(label)}"` : ""}><i style="width:${value}%"></i></div>`;
}

function gallery(images = [4, 6, 8, 9, 12, 2]) {
  return `<div class="workspace-gallery">${images.map((id, index) => `<button data-modal="gallery.view" aria-label="Открыть работу ${index + 1}"><img src="${heroImage(String(id).padStart(2, "0"))}" alt="Пример detailing-работы ${index + 1}" loading="lazy"><span>${["BMW X5 · керамика", "Mercedes E · полировка", "Range Rover · PPF", "Porsche 911 · детейлинг", "Audi Q7 · химчистка", "BMW M4 · защита"][index] || "Пример работы"}</span></button>`).join("")}</div>`;
}

