function dashboardPublicAction(ctx, config) {
  if (ctx.role === "admin") return "";
  return linkBtn("Публичный профиль", config.publicPath, { cls: "secondary", iconName: "eye" });
}

function dashboardNavigation(ctx, active) {
  const groups = [
    ["Рабочее пространство", ["overview", "vacancies", "resume", "gigs", "orders", "purchases", "promos", "favorites", "analytics"]],
    ["Репутация и контент", ["portfolio", "certificates", "reviews", "team", "branches"]],
    ["Аккаунт", ["profile", "payments", "privacy"]],
  ];
  const icons = { overview: "grid", vacancies: "briefcase", resume: "file", gigs: "zap", orders: "clipboard", purchases: "store", promos: "ticket", favorites: "heart", analytics: "bot", portfolio: "image", certificates: "award", reviews: "star", team: "users", branches: "pin", profile: "user", payments: "card", privacy: "lock" };
  const counts = { vacancies: 12, gigs: 3, orders: 3, purchases: 4, promos: 8, reviews: 12, favorites: ctx.favorites.size };
  return groups.map(([label, keys]) => {
    const visible = keys.filter((key) => ROLES[ctx.role].tabs.includes(key));
    return visible.length ? `<div class="dashboard-nav-group"><span>${label}</span><nav>${visible.map((key) => `<button class="${active === key ? "active" : ""}" data-action="dashboard-tab" data-tab="${key}" aria-current="${active === key ? "page" : "false"}">${icon(icons[key])}<span>${DASHBOARD_TABS[key]}</span>${counts[key] !== undefined ? `<b>${counts[key]}</b>` : ""}</button>`).join("")}</nav></div>` : "";
  }).join("");
}

function dashboardMetricTab(role, index) {
  const targets = {
    employer: ["vacancies", "vacancies", "gigs", "reviews"], worker: ["resume", "resume", "gigs", "reviews"],
    client: ["orders", "orders", "favorites", "orders"], supplier: ["purchases", "purchases", "purchases", "reviews"],
    partner: ["promos", "promos", "analytics", "analytics"], admin: ["profile", "profile", "profile", "profile"],
  };
  return targets[role][index];
}

function dashboardQueuePath(role) {
  return { employer: "/specialists", worker: "/gigs", client: "/orders", supplier: "/suppliers", partner: "/promos", admin: "/admin" }[role];
}

function dashboardDetailPath(role) {
  return { employer: "/gigs/gig-016", worker: "/gigs/gig-016", client: "/orders/order-001", supplier: "/suppliers/purchase-001", partner: "/promos/promo-001", admin: "/admin" }[role];
}

function dashboardOverview(ctx, config) {
  const role = ROLES[ctx.role];
  const recent = ctx.role === "employer" ? [
    ["Мастер по PPF", "Казань · полный день", "90–125 тыс. ₽", "12 откликов", "/vacancies/vac-022"],
    ["Детейлер-полировщик", "Москва · сменный график", "от 110 тыс. ₽", "8 откликов", "/vacancies/vac-021"],
    ["Мойщик автомобилей", "Санкт-Петербург · 2/2", "65–80 тыс. ₽", "5 откликов", "/vacancies/vac-020"],
  ] : ctx.role === "worker" ? [
    ["Универсал на выходные", "Сегодня · Shine&Go", "9 500 ₽", "Подтверждена", "/gigs/gig-016"],
    ["Мойщик на смену", "Завтра, 09:00 · CleanLab", "2 500 ₽", "Ожидает", "/gigs/gig-015"],
    ["Полировщик на автомобиль", "18 ноября · АвтоПрофи", "7 000 ₽", "Отклик отправлен", "/gigs/gig-014"],
  ] : ctx.role === "client" ? ORDERS.map((item) => [item.title, `${item.city} · ${item.schedule}`, item.salary, item.experience, `/orders/${item.id}`]) : ctx.role === "supplier" ? PURCHASES.map((item) => [item.title, item.schedule, item.salary, item.tags[0], `/suppliers/${item.id}`]) : PROMOS.map((item) => [item.title, `${item.city} · ${item.schedule}`, item.salary, item.experience, `/promos/${item.id}`]);
  const queueTitle = { employer: "Новые кандидаты", worker: "Ближайшая смена", client: "Предложения по заявке", supplier: "Закупка близка к цели", partner: "Акции требуют внимания", admin: "Очередь модерации" }[ctx.role];
  return `<div class="dashboard-metrics">${config.metrics.map(([value, label, note], index) => `<button class="dashboard-metric" data-action="dashboard-tab" data-tab="${dashboardMetricTab(ctx.role, index)}"><span>${label}</span><strong class="${index === 0 ? "accent" : ""}">${value}</strong><small>${note}</small></button>`).join("")}</div><div class="dashboard-workspace"><div class="dashboard-main-column">${panel("Что требует внимания", `<div class="attention-list">${config.tasks.map(([title, text, tab, count], index) => `<article><span class="attention-icon ${index === 0 ? "urgent" : ""}">${icon(index === 0 ? "bell" : index === 1 ? "clipboard" : "calendar")}</span><div><b>${title}</b><p>${text}</p></div><span class="attention-count">${count}</span><button data-action="dashboard-tab" data-tab="${tab}" aria-label="Открыть: ${esc(title)}">${icon("chevron")}</button></article>`).join("")}</div>`, { eyebrow: "Сегодня" })}${panel(queueTitle, dashboardQueue(ctx), { actions: `<button class="workspace-link" data-path="${dashboardQueuePath(ctx.role)}">Все ${icon("chevron", "sm")}</button>` })}${panel(ctx.role === "employer" ? "Активные вакансии" : ctx.role === "worker" ? "Мои смены и отклики" : ctx.role === "client" ? "Мои заявки" : ctx.role === "supplier" ? "Активные закупки" : "Активные предложения", `<div class="dashboard-recent">${recent.map(([title, meta, price, status, path], index) => `<a href="#${path}" data-path="${path}"><span class="recent-number">0${index + 1}</span><div><b>${title}</b><span>${meta}</span></div><strong>${price}</strong>${badge(status, index === 0 ? "ok" : "")}${icon("chevron", "sm")}</a>`).join("")}</div>`, { actions: btn(config.primary[0], { modal: config.primary[1], path: config.primary[3] || "", cls: "sm secondary", iconName: config.primary[2] }) })}</div><aside class="dashboard-rail">${panel("Быстрые действия", `<div class="dashboard-quick">${config.quick.map(([modal, ico, title, text, path]) => `<button data-${modal ? "modal" : "path"}="${modal || path}"><span>${icon(ico)}</span><div><b>${title}</b><small>${text}</small></div>${icon("plus", "sm")}</button>`).join("")}</div>`)}<section class="dashboard-next"><div class="workspace-kicker">${ctx.role === "worker" ? "Ближайшая смена" : "На этой неделе"}</div><strong>${ctx.role === "client" ? "12" : "18"}<small>ноября</small></strong><h3>${ctx.role === "supplier" ? "Завершение закупки" : ctx.role === "partner" ? "Отчёт по активациям" : ctx.role === "client" ? "Химчистка RAV4" : "Смена в Shine&Go"}</h3><p>${ctx.role === "client" ? "Детейлинг Партнёр · 14:30" : "Москва, Тверская, 12 · 09:00–21:00"}</p><div>${personAvatar(ctx.role === "employer" ? "Михаил Соколов" : role.name)}<span>${ctx.role === "employer" ? "Михаил подтвердил выход" : "Напомним заранее"}</span></div>${linkBtn("Открыть детали", dashboardDetailPath(ctx.role), { cls: "secondary block" })}</section>${panel("Профиль и доверие", `<div class="profile-completion"><div><strong>82%</strong><span>заполнено</span></div>${progress(82)}<p>Добавьте примеры работ и уточните контакты, чтобы получать больше откликов.</p><button class="workspace-link" data-action="dashboard-tab" data-tab="profile">Дополнить профиль ${icon("chevron", "sm")}</button></div>`)}${panel("Тариф «Профессиональный»", `<div class="subscription-row">${badge("Активен", "ok")}<span>до 15 декабря</span></div><p>Приоритет в каталоге, аналитика и продвижение публикаций.</p><button class="workspace-link" data-action="dashboard-tab" data-tab="payments">Управить подпиской ${icon("chevron", "sm")}</button>`, { cls: "dashboard-subscription" })}</aside></div>`;
}

function dashboardQueue(ctx) {
  if (ctx.role === "worker") return `<div class="next-shift-card"><div class="shift-date"><b>18</b><span>ноября<br>среда</span></div><div><h3>Универсал на выходные</h3><p>Shine&Go · Москва, Тверская, 12</p><div class="row">${badge("09:00–21:00")}${badge("9 500 ₽", "accent")}</div></div>${linkBtn("Детали смены", "/gigs/gig-016", { cls: "secondary" })}</div><div class="callout ok mt-2"><b>Всё готово к выходу</b><p class="small mb-0">Адрес и контакт руководителя доступны в переписке.</p></div>`;
  if (ctx.role === "supplier") return `<div class="purchase-focus"><div class="row between"><div><b>Полировальная паста Koch Chemie</b><p class="small muted mb-0">14 из 20 литров · 8 студий</p></div><strong class="accent">70%</strong></div>${progress(70)}<div class="row between mt-2"><span class="small muted">До оптовой цены осталось 6 литров</span>${linkBtn("Открыть", "/suppliers/purchase-001", { cls: "sm secondary" })}</div></div>`;
  if (ctx.role === "partner") return `<div class="partner-focus"><strong>142</strong><div><b>Активации за ноябрь</b><p>Показы → активации: 38%</p></div><span class="trend-up">+18%</span></div><div class="mini-bars" aria-label="Динамика активаций за 7 дней">${[42, 58, 47, 73, 66, 89, 94].map((height, i) => `<i style="height:${height}%" title="${8 + i} ноября"></i>`).join("")}</div>`;
  if (ctx.role === "admin") return `<div class="candidate-list">${[["Shine&Go", "Документы компании", "7 мин"], ["Детейлинг Партнёр", "Запрос прав на профиль", "24 мин"]].map(([name, meta, time]) => `<a href="#/admin" data-path="/admin">${brandAvatar(name)}<div><b>${name}</b><span>${meta}</span></div><time>${time}</time>${icon("chevron", "sm")}</a>`).join("")}</div>`;
  const candidates = ctx.role === "client" ? [["Михаил Соколов", "Химчистка RAV4 · 14 500 ₽", "9,6"], ["Александр Волков", "Химчистка RAV4 · 16 000 ₽", "9,2"]] : [["Михаил Соколов", "Мастер по PPF · 6 лет опыта", "96%"], ["Александр Волков", "Детейлер-полировщик · 4 года", "89%"], ["Дмитрий Ким", "Мойщик автомобилей · 2 года", "84%"]];
  return `<div class="candidate-list">${candidates.map(([name, meta, match]) => `<a href="#/profile/${name === "Михаил Соколов" ? "worker-001" : name === "Александр Волков" ? "worker-002" : "worker-003"}" data-path="/profile/${name === "Михаил Соколов" ? "worker-001" : name === "Александр Волков" ? "worker-002" : "worker-003"}">${personAvatar(name)}<div><b>${name}</b><span>${meta}</span></div><span class="match-score">${match}<small>${ctx.role === "client" ? "рейтинг" : "совпадение"}</small></span>${icon("chevron", "sm")}</a>`).join("")}</div>`;
}

