function profileType(id) {
  if (id.startsWith("company")) return "company";
  if (id.startsWith("supplier")) return "supplier";
  if (id.startsWith("partner")) return "partner";
  if (id.startsWith("client")) return "client";
  return "worker";
}

function profileFacts(type, config = {}) {
  if (type === "worker") return [["Специализация", config.subtitle || "Полировка · PPF · керамика"], ["Опыт работы", config.experience || "6 лет"], ["Желаемая зарплата", config.salary || "от 90 000 ₽"], ["График", "Полный день · подработки"], ["Гражданство", "Россия"], ["Готовность", `Командировки · выезд: ${config.city || "Москва"}`]];
  if (type === "company") return [["Тип бизнеса", "Детейлинг-студия"], ["Филиалы", "3 в Казани"], ["График", "Ежедневно, 09:00–21:00"], ["На платформе", "С марта 2026"]];
  if (type === "supplier") return [["Минимальный заказ", "от 50 000 ₽"], ["Доставка", "По России · 2–5 дней"], ["Скидка партнёрам", "до 30%"], ["Документы", "Счета и сертификаты"]];
  return [["Город", "Москва"], ["На платформе", "С марта 2026"], ["Статус", "Документы проверены"], ["Отвечает", "Обычно в течение часа"]];
}

function profileContact(ctx, type, config) {
  const revealed = ctx.revealedContacts.has(config.key);
  return `${panel("Связаться", `<div class="profile-contact-status"><i></i><span>${type === "worker" ? "Открыт к предложениям" : "Обычно отвечает в течение часа"}</span></div>${btn(config.primary, { modal: config.modal || "", path: config.path || "", cls: "primary block", iconName: type === "worker" ? "send" : "message" })}<button class="btn secondary block mt-1" data-action="profile-follow" data-profile="${config.key}" aria-pressed="${ctx.followedProfiles.has(config.key)}">${icon(ctx.followedProfiles.has(config.key) ? "check" : "plus")}<span>${ctx.followedProfiles.has(config.key) ? "Вы подписаны" : "Подписаться"}</span></button><div class="profile-private-contact"><div>${icon("phone")}<span>${revealed ? "+7 (999) 521-22-51" : "+7 (999) •••-••-••"}</span></div><button data-action="contact-reveal" data-profile="${config.key}">${revealed ? "Скрыть" : "Показать телефон"}</button><small>Контакт виден только после вашего действия</small></div>`)}${panel(type === "worker" ? "Проверки специалиста" : "Надёжный профиль", `<div class="trust-list"><div>${icon("shield")}<span><b>Личность и документы</b><small>Проверено командой СОУС</small></span>${icon("check", "sm")}</div>${type === "worker" ? `<div>${icon("award")}<span><b>2 сертификата</b><small>Подлинность подтверждена</small></span>${icon("check", "sm")}</div>` : `<div>${icon("store")}<span><b>Данные компании</b><small>Сведения сверены с ЕГРЮЛ</small></span>${icon("check", "sm")}</div>`}<div>${icon("star")}<span><b>${config.reviews} проверенных отзывов</b><small>Только после реальных заказов</small></span></div></div>`)}<button class="profile-report" data-modal="report.create">${icon("flag", "sm")} Пожаловаться на профиль</button>`;
}

function workerProfile(tab, config) {
  if (tab === "portfolio") return panel("Портфолио специалиста", `<p class="workspace-intro">38 завершённых работ · полировка, защита и химчистка</p>${gallery([4, 6, 8, 9, 12, 2])}`);
  if (tab === "certs") return panel("Подтверждённая квалификация", `<div class="profile-certificates"><article><span>${icon("award", "xl")}</span><div><h3>Мастер детейлинга</h3><p>Учебный центр СОУС · 12 октября 2026</p><b>UC-2026-001</b></div>${badge("Подтверждён", "ok")}${linkBtn("Проверить", "/training/certificate/UC-2026-001", { cls: "sm secondary" })}</article><article><span>${icon("award", "xl")}</span><div><h3>Установка PPF · Advanced</h3><p>Практический курс · 24 сентября 2026</p><b>PPF-2026-184</b></div>${badge("Подтверждён", "ok")}</article></div>`);
  if (tab === "reviews") return panel("Отзывы о работе", reviewsBlock());
  return `${panel("О специалисте", `<p class="profile-description">${config.description}</p><div class="skill-cloud">${["Восстановительная полировка", "Установка PPF", "Керамические составы", "Химчистка кожи", "Работа с матовым ЛКП", "Фотоотчёт"].map((skill) => badge(skill)).join("")}</div>`)}${panel("Профессиональные данные", `<div class="profile-facts">${profileFacts("worker", config).map(([label, value]) => `<div><span>${label}</span><b>${value}</b></div>`).join("")}</div>`)}${panel("Опыт работы", `<div class="experience-timeline"><article><time>2022 — сейчас</time><div><h3>АвтоПрофи · старший детейлер</h3><p>Полировка и защита премиальных автомобилей, контроль качества, обучение младших мастеров.</p></div></article><article><time>2020 — 2022</time><div><h3>CleanLab · детейлер</h3><p>Комплексная подготовка автомобилей, химчистка салона, керамические покрытия.</p></div></article></div>`)}${panel("Избранные работы", gallery([4, 6, 8]), { actions: `<button class="workspace-link" data-action="profile-tab" data-tab="portfolio">Все 38 работ ${icon("chevron", "sm")}</button>` })}`;
}

function companyProfile(tab, config) {
  if (tab === "vacancies") return panel("Открытые вакансии", `<div class="profile-opportunities">${VACANCIES.map((item) => `<a href="#/vacancies/${item.id}" data-path="/vacancies/${item.id}"><div><h3>${item.title}</h3><p>${item.city} · ${item.schedule} · ${item.experience}</p><div>${item.tags.map((tag) => badge(tag)).join("")}</div></div><strong>${item.salary}</strong>${icon("chevron")}</a>`).join("")}</div>`);
  if (tab === "services") return panel("Услуги и ориентировочные цены", `<div class="price-list">${[["Диагностика и консультация", "Бесплатно", "Осмотр, тест материалов и смета"], ["Восстановительная полировка", "от 18 000 ₽", "Локальная или полная обработка"], ["Керамическое покрытие", "от 32 000 ₽", "Подготовка и два слоя состава"], ["Оклейка PPF", "от 65 000 ₽", "Зоны риска или полный кузов"], ["Глубокая химчистка салона", "от 12 000 ₽", "Текстиль, кожа и потолок"]].map(([name, price, text]) => `<article><div><h3>${name}</h3><p>${text}</p></div><strong>${price}</strong>${btn("Записаться", { modal: "order.create", cls: "sm secondary" })}</article>`).join("")}</div><p class="workspace-footnote">Точная стоимость определяется после осмотра автомобиля и согласования объёма работ.</p>`);
  if (tab === "portfolio") return panel("Работы студии", gallery([6, 4, 8, 12, 2, 9]));
  if (tab === "reviews") return panel("Отзывы клиентов", reviewsBlock());
  return `${panel("О студии", `<p class="profile-description">${config.description}</p><div class="skill-cloud">${["PPF", "Полировка", "Керамика", "Химчистка", "Детейлинг салона"].map((skill) => badge(skill)).join("")}</div>`)}${panel("Популярные услуги", `<div class="service-cards">${[["Полировка кузова", "от 18 000 ₽", "wrench"], ["Керамическая защита", "от 32 000 ₽", "shield"], ["Оклейка PPF", "от 65 000 ₽", "image"]].map(([name, price, ico]) => `<button data-action="profile-tab" data-tab="services"><span>${icon(ico)}</span><h3>${name}</h3><p>${price}</p>${icon("chevron", "sm")}</button>`).join("")}</div>`, { actions: `<button class="workspace-link" data-action="profile-tab" data-tab="services">Все услуги ${icon("chevron", "sm")}</button>` })}${panel("Последние работы", gallery([6, 4, 8]), { actions: `<button class="workspace-link" data-action="profile-tab" data-tab="portfolio">Портфолио ${icon("chevron", "sm")}</button>` })}${panel("Центральный филиал", miniMap("Казань", "ул. Пушкина, 24"))}`;
}

function businessProfile(ctx, type, tab, config) {
  if (tab === "reviews") return panel("Отзывы", reviewsBlock());
  if (tab === "prices") return panel("Прайс для бизнеса", table(["Товар", "Фасовка", "Цена", "Наличие"], [["Green Star · универсальный очиститель", "1 л", "1 250 ₽", badge("В наличии", "ok")], ["Nano Magic Shampoo", "1 л", "1 480 ₽", badge("В наличии", "ok")], ["Heavy Cut H9.02", "1 л", "1 850 ₽", badge("Под заказ", "warn")], ["Микрофибра Professional", "10 шт.", "3 200 ₽", badge("В наличии", "ok")]]), { actions: btn("Скачать полный прайс", { action: "download", cls: "secondary", iconName: "download" }) });
  if (tab === "purchases") return panel("Активные коллективные закупки", `<div class="profile-purchases">${PURCHASES.map((item, index) => `<article><div class="row between"><h3>${item.title}</h3>${badge(item.tags[0], "accent")}</div><p>${item.description}</p>${progress(index === 0 ? 70 : 64)}<div class="row between"><strong>${item.salary}</strong>${linkBtn("Участвовать", `/suppliers/${item.id}`, { cls: "sm primary" })}</div></article>`).join("")}</div>`);
  if (tab === "promos") return panel("Действующие акции", `<div class="profile-promos">${PROMOS.map((item) => `<a href="#/promos/${item.id}" data-path="/promos/${item.id}"><span>${icon("ticket", "lg")}</span><div><h3>${item.title}</h3><p>${item.description}</p><small>${item.schedule} · ${item.experience}</small></div><strong>${item.salary}</strong>${icon("chevron")}</a>`).join("")}</div>`);
  if (tab === "news") return panel("Новости компании", `<div class="profile-news">${[["Обновили линейку для матовых покрытий", "Разбираем новые составы и делимся схемой безопасной мойки без добавления блеска.", "12 ноября"], ["Открыта коллективная закупка для студий", "Объединяем заказы полировальных паст и микрофибры. Оптовая цена действует до 20 ноября.", "8 ноября"]].map(([title, text, date]) => `<article><span class="workspace-kicker">${date}</span><h3>${title}</h3><p>${text}</p><button class="workspace-link" data-path="/feed">Читать в ленте ${icon("chevron", "sm")}</button></article>`).join("")}</div>`);
  const about = panel(type === "supplier" ? "О поставщике" : type === "partner" ? "О партнёре" : "Об автовладельце", `<p class="profile-description">${config.description}</p><div class="profile-facts">${profileFacts(type).map(([label, value]) => `<div><span>${label}</span><b>${value}</b></div>`).join("")}</div>`);
  const extra = type === "partner" ? businessProfile(ctx, type, "promos", config) : type === "supplier" ? `${panel("Условия работы", `<div class="service-cards">${[["Официальные поставки", "Документы и гарантия", "shield"], ["Коллективные закупки", "Экономия до 30%", "users"], ["Помощь с подбором", "Расчёт под процессы", "calculator"]].map(([title, text, ico]) => `<div><span>${icon(ico)}</span><h3>${title}</h3><p>${text}</p></div>`).join("")}</div>`)}${miniMap(config.city, "Склад: Волгоградский проспект, 42")}` : "";
  return `${about}${extra}`;
}

export function publicProfilePage(ctx, id) {
  const type = profileType(id);
  const source = type === "worker" ? SPECIALISTS : type === "company" ? COMPANIES : type === "supplier" ? SUPPLIERS : [];
  const item = source.find((entry) => entry.id === id);
  const base = { ...PROFILE_CONFIGS[type], key: `${type}:${id}` };
  const config = item ? { ...base, name: item.title, subtitle: item.company, city: item.city, description: item.description, salary: item.salary, experience: type === "worker" ? item.schedule.replace(/^Опыт\s+/, "") : base.experience, secondaryValue: type === "worker" ? item.schedule.replace(/^Опыт\s+/, "") : type === "company" ? item.experience.match(/\d+/)?.[0] : type === "supplier" ? "4" : "12", rating: (type === "company" ? item.salary : item.experience).match(/[\d,]+/)?.[0] || base.rating } : base;
  const active = config.tabs.some(([key]) => key === ctx.profileTab) ? ctx.profileTab : config.tabs[0][0];
  const isPerson = type === "worker" || type === "client";
  const body = type === "worker" ? workerProfile(active, config) : type === "company" ? companyProfile(active, config) : businessProfile(ctx, type, active, config);
  return `<div class="public-profile-page"><div class="profile-cover" data-hero-image="${config.image}"></div><div class="wrap"><a class="workspace-back profile-back" href="#/${type === "company" ? "companies" : type === "supplier" ? "suppliers" : type === "partner" ? "promos" : "specialists"}" data-path="/${type === "company" ? "companies" : type === "supplier" ? "suppliers" : type === "partner" ? "promos" : "specialists"}">${icon("back", "sm")} ${type === "company" ? "Все компании" : type === "supplier" ? "Все поставщики" : type === "partner" ? "Все акции" : "Все специалисты"}</a><section class="profile-hero"><div class="profile-hero-main">${isPerson ? personAvatar(config.name, "profile-main-avatar") : brandAvatar(config.name, "profile-main-avatar")}<div class="profile-identity"><div class="row"><span class="workspace-kicker">${config.kind}</span><span class="profile-online"><i></i> в сети</span></div><h1>${config.name}</h1><p>${config.subtitle}</p><div class="profile-location">${icon("pin", "sm")} ${config.city}<span>·</span> На платформе с марта 2026</div><div class="profile-badges">${badge("Документы проверены", "ok")}${type === "worker" ? badge("Сертифицирован", "accent") : ""}${type === "worker" ? badge("Доступен для подработок", "info") : ""}</div></div></div><div class="profile-hero-actions">${btn(config.primary, { modal: config.modal || "", path: config.path || "", cls: "primary", iconName: type === "worker" ? "send" : "message" })}${btn("", { action: "share", cls: "secondary icon-only", iconName: "share", attrs: 'aria-label="Поделиться профилем"' })}${btn("", { modal: "report.create", cls: "ghost icon-only", iconName: "more", attrs: 'aria-label="Дополнительные действия"' })}</div><div class="profile-hero-metrics"><button data-action="profile-tab" data-tab="reviews"><strong>${config.rating}<small>/10</small></strong><span>${config.reviews} отзывов</span></button><div><strong>${config.secondaryValue || (type === "worker" ? "6 лет" : type === "company" ? "3" : type === "supplier" ? "4" : "12")}</strong><span>${type === "worker" ? "опыта" : type === "company" ? "филиала" : type === "supplier" ? "закупки" : "публикаций"}</span></div><div><strong>${config.followers + (ctx.followedProfiles.has(config.key) ? 1 : 0)}</strong><span>подписчиков</span></div><div><strong>${type === "worker" ? "38" : type === "company" ? "24" : "96%"}</strong><span>${type === "worker" || type === "company" ? "работ" : "рекомендуют"}</span></div></div></section><nav class="profile-tabs" aria-label="Разделы профиля">${config.tabs.map(([key, label, count]) => `<button class="${active === key ? "active" : ""}" data-action="profile-tab" data-tab="${key}" aria-current="${active === key ? "page" : "false"}">${label}${count !== undefined ? `<span>${count}</span>` : ""}</button>`).join("")}</nav><div class="profile-content"><main>${body}</main><aside>${profileContact(ctx, type, config)}</aside></div></div><div class="profile-mobile-action">${btn(config.primary, { modal: config.modal || "", path: config.path || "", cls: "primary", iconName: type === "worker" ? "send" : "message" })}${btn("", { action: "share", cls: "secondary icon-only", iconName: "share", attrs: 'aria-label="Поделиться профилем"' })}</div></div>${footer()}`;
}

function detailHeader({ type, item, image, stats, badges: labels, action, secondary = "" }) {
  return `<div class="catalog-detail-page"><div class="wrap"><a class="workspace-back" href="#/${type}" data-path="/${type}">${icon("back", "sm")} ${type === "vacancies" ? "Все вакансии" : type === "gigs" ? "Все подработки" : type === "orders" ? "Все заявки" : "Все акции"}</a><section class="catalog-detail-hero"><div class="catalog-detail-copy"><div class="row">${labels.map((label, index) => badge(label, index === 0 ? "accent" : "")).join("")}</div><h1>${item.title}</h1><div class="detail-publisher">${type === "orders" ? personAvatar(item.company) : brandAvatar(item.company)}<div><b>${item.company}</b><span>${item.city} · документы проверены</span></div>${icon("shield", "sm")}</div><div class="catalog-detail-stats">${stats.map(([value, label], index) => `<div><strong class="${index === 0 ? "accent" : ""}">${value}</strong><span>${label}</span></div>`).join("")}</div><div class="catalog-detail-actions">${action}${secondary}${btn("", { action: "favorite", cls: "secondary icon-only", iconName: "heart", attrs: `aria-label="Сохранить" data-id="${type}:${item.id}"` })}${btn("", { action: "share", cls: "ghost icon-only", iconName: "share", attrs: 'aria-label="Поделиться"' })}</div></div><div class="catalog-detail-art" data-hero-image="${image}"><span>${type === "promos" ? "Предложение партнёра" : type === "vacancies" ? "Работа в проверенной компании" : type === "gigs" ? "Подработка с понятными условиями" : "Прямая заявка автовладельца"}</span></div></section></div>`;
}

function detailFooter(label = "Откликнуться") {
  return `</div><div class="detail-mobile-bar"><span>СОУС · безопасная сделка</span>${btn(label, { action: "mobile-detail-action", cls: "primary" })}</div>${footer()}`;
}

function promoDetail(item) {
  const cashback = item.id === "promo-001";
  const action = cashback ? btn("Участвовать в кешбэке", { path: "/promos/cashback/promo-001", cls: "primary lg", iconName: "ticket" }) : btn("Активировать промокод", { modal: "promo.qr", cls: "primary lg", iconName: "qr" });
  const secondary = btn("Как это работает", { action: "scroll-terms", cls: "secondary lg", iconName: "info" });
  const content = `${panel("Что вы получаете", `<p class="profile-description">${item.description}</p><div class="promo-benefit"><div><span>${cashback ? "Максимальный кешбэк" : "Ваша выгода"}</span><strong>${item.salary}</strong><p>${cashback ? "Сумма растёт с каждой подтверждённой активацией. Текущий размер — 1 250 ₽." : "Скидка применяется после сканирования QR сотрудником партнёра."}</p></div><span class="promo-benefit-icon">${icon(cashback ? "card" : "ticket", "xl")}</span></div>${cashback ? `<div class="cashback-ladder">${[["1 000 ₽", "старт"], ["1 250 ₽", "сейчас"], ["3 000 ₽", "максимум"]].map(([value, label], index) => `<div class="${index === 1 ? "active" : ""}"><strong>${value}</strong><span>${label}</span></div>`).join("")}</div>` : ""}`)}${panel("Как воспользоваться", `<div class="promo-steps">${[["Выберите услугу", cashback ? "Запишитесь на химчистку у партнёра и оплатите обычным способом." : "Покажите страницу акции сотруднику до оплаты."], ["Подтвердите участие", cashback ? "Загрузите фото или PDF чека в личном кабинете." : "Откройте персональный QR — его сканирует только сотрудник."], ["Получите выгоду", cashback ? "После проверки чека кешбэк будет доступен к выплате через СБП." : "После зелёного подтверждения скидка применится к заказу."]].map(([title, text], index) => `<article><span>0${index + 1}</span><div><h3>${title}</h3><p>${text}</p></div></article>`).join("")}</div>`, { eyebrow: "Три простых шага" })}${panel("Условия и ограничения", `<div class="terms-grid">${infoItem("calendar", "Срок действия", item.schedule)}${infoItem("pin", "Город", item.city)}${infoItem("ticket", "Активация", cashback ? "Участие и загрузка чека" : "Персональный QR на точке")}${infoItem("users", "Кто может участвовать", "Автовладельцы и специалисты СОУС")}</div><ul class="detail-list"><li>Одна активация на пользователя в рамках предложения.</li><li>Не суммируется с другими специальными предложениями партнёра.</li><li>Сохраните чек до завершения проверки и начисления выгоды.</li></ul>`)}${panel("Где воспользоваться", miniMap(item.city, "Детейлинг Партнёр · Центральный район"))}`;
  const rail = `<section class="detail-action-card"><span class="workspace-kicker">Готово к использованию</span><div class="detail-action-value">${item.salary}</div><p>${cashback ? "Участвуйте в программе и получите кешбэк после проверки чека." : "Активируйте QR перед оплатой. Код действует 24 часа."}</p><div class="promo-availability"><div><span>Осталось активаций</span><b>42 из 100</b></div>${progress(58)}</div>${action}<button class="btn secondary block mt-1" data-action="favorite" data-id="promos:${item.id}">${icon("heart")}<span>Сохранить акцию</span></button><small>${icon("shield", "sm")} Условия проверены модерацией СОУС</small></section>${panel("Партнёр", `<div class="detail-company">${brandAvatar(item.company, "lg")}<div><h3>${item.company}</h3><p>${item.city} · на платформе с 2026</p></div></div><div class="detail-company-stats"><span><b>9,7</b> рейтинг</span><span><b>32</b> отзыва</span><span><b>8</b> акций</span></div>${linkBtn("Открыть профиль", entityProfilePath(item.company), { cls: "secondary block", iconName: "user" })}`)}${panel("Нужна помощь?", `<p class="small muted">Если сотрудник не может применить предложение, не сканируйте код повторно. Напишите нам.</p>${linkBtn("Поддержка СОУС", "/contacts", { cls: "ghost block", iconName: "message" })}`)}`;
  return `${detailHeader({ type: "promos", item, image: "11", stats: [[item.salary, cashback ? "максимум кешбэка" : "ваша выгода"], [item.schedule.replace("До ", ""), "действует до"], ["42", "активаций осталось"]], badges: item.tags, action, secondary })}<div class="wrap"><div class="catalog-detail-layout"><main>${content}</main><aside class="catalog-detail-rail">${rail}</aside></div><section class="related-section"><div class="workspace-panel-head"><div><span class="workspace-kicker">Может быть полезно</span><h2>Другие предложения</h2></div>${linkBtn("Все акции", "/promos", { cls: "secondary" })}</div><div class="related-grid">${PROMOS.filter((promo) => promo.id !== item.id).map((promo) => `<a href="#/promos/${promo.id}" data-path="/promos/${promo.id}"><span>${icon("ticket", "lg")}</span><h3>${promo.title}</h3><p>${promo.company} · ${promo.city}</p><strong>${promo.salary}</strong><small>${promo.schedule}</small></a>`).join("")}</div></section></div>${detailFooter(cashback ? "Участвовать" : "Показать QR")}`;
}

function vacancyDetail(item) {
  const action = btn("Откликнуться на вакансию", { modal: "vacancy.apply", cls: "primary lg", iconName: "send" });
  const companyPath = entityProfilePath(item.company);
  const content = `${panel("О вакансии", `<p class="profile-description">${item.description}</p><p class="prose">Вы будете отвечать за качество выполнения работ, соблюдение регламента и понятную коммуникацию с командой. Нестандартные задачи, сроки и дополнительные условия согласовываются до начала.</p>`)}${panel("Ваши задачи", `<ul class="detail-list check-list"><li>Выполнение работ по специализации «${item.title}» по стандартам компании.</li><li>Подготовка рабочей зоны, материалов и оборудования.</li><li>Контроль качества, фотоотчёт и участие в сдаче результата.</li><li>Поддержание порядка и соблюдение технологии безопасной работы.</li></ul>`)}${panel("Что для нас важно", `<div class="requirements-grid">${[[item.experience, `Профильный опыт по направлению «${item.title}»`, "briefcase"], ["Внимание к деталям", "Проверяете результат и сразу обозначаете риски", "eye"], ["Ответственность", "Соблюдаете сроки и договорённости", "shield"], ["Командная работа", "Готовы к разбору и обратной связи", "users"]].map(([title, text, ico]) => `<article>${icon(ico)}<h3>${title}</h3><p>${text}</p></article>`).join("")}</div>`)}${panel("Условия и бенефиты", `<div class="benefit-list">${[[`${item.salary} на руки`, "Понятная система оплаты и регулярные выплаты"], [item.schedule, "Согласованный график без скрытых переработок"], ["Обучение и сертификация", "Возможность повышать квалификацию в СОУС"], ["Материалы и инструмент", "Всё необходимое предоставляет компания"]].map(([title, text]) => `<div>${icon("check")}<span><b>${title}</b><small>${text}</small></span></div>`).join("")}</div>`)}${panel("Место работы", miniMap(item.city, "Центральный филиал · точный адрес в отклике"))}${panel("Отзывы о работодателе", reviewsBlock(), { actions: linkBtn("Все отзывы", companyPath, { cls: "secondary" }) })}`;
  const rail = `<section class="detail-action-card"><span class="workspace-kicker">Отклик занимает 2 минуты</span><div class="detail-action-value">${item.salary}</div><p>Работодатель увидит ваш профиль и сопроводительное письмо. Среднее время ответа — 3 часа.</p>${action}${linkBtn("Написать работодателю", "/messages", { cls: "secondary block mt-1", iconName: "message" })}<small>${icon("shield", "sm")} Можно отозвать отклик в любой момент</small></section>${panel("Работодатель", `<div class="detail-company">${brandAvatar(item.company, "lg")}<div><h3>${item.company}</h3><p>Детейлинг-студия · ${item.city}</p></div></div><div class="trust-list mt-2"><div>${icon("shield")}<span><b>Документы проверены</b><small>Данные сверены с ЕГРЮЛ</small></span>${icon("check", "sm")}</div><div>${icon("star")}<span><b>9,8 / 10</b><small>42 отзыва сотрудников и клиентов</small></span></div><div>${icon("briefcase")}<span><b>12 открытых вакансий</b><small>3 филиала в Казани</small></span></div></div>${linkBtn("Профиль компании", companyPath, { cls: "secondary block mt-2" })}`)}${panel("Как СОУС защищает", `<ul class="safety-list"><li>Компании проходят проверку документов.</li><li>Жалобы рассматриваются в течение 24 часов.</li><li>Условия и переписка сохраняются в платформе.</li></ul><button class="profile-report" data-modal="report.create">${icon("flag", "sm")} Пожаловаться на вакансию</button>`)}`;
  return `${detailHeader({ type: "vacancies", item, image: "06", stats: [[item.salary, "в месяц на руки"], [item.schedule, "график"], [item.experience, "опыт"]], badges: item.tags, action, secondary: linkBtn("О компании", companyPath, { cls: "secondary lg" }) })}<div class="wrap"><div class="catalog-detail-layout"><main>${content}</main><aside class="catalog-detail-rail">${rail}</aside></div><section class="related-section"><div class="workspace-panel-head"><div><span class="workspace-kicker">Похожие условия</span><h2>Другие вакансии</h2></div>${linkBtn("Все вакансии", "/vacancies", { cls: "secondary" })}</div><div class="related-grid">${VACANCIES.filter((vacancy) => vacancy.id !== item.id).slice(0, 3).map((vacancy) => `<a href="#/vacancies/${vacancy.id}" data-path="/vacancies/${vacancy.id}"><span>${icon("briefcase", "lg")}</span><h3>${vacancy.title}</h3><p>${vacancy.company} · ${vacancy.city}</p><strong>${vacancy.salary}</strong><small>${vacancy.schedule} · ${vacancy.experience}</small></a>`).join("")}</div></section></div>${detailFooter()}`;
}

function taskDetail(ctx, type, item) {
  const isGig = type === "gigs";
  const action = btn(isGig ? "Откликнуться на смену" : "Предложить услуги", { modal: isGig ? "gig.apply" : "order.apply", cls: "primary lg", iconName: "send" });
  const content = `${panel(isGig ? "Что нужно сделать" : "Задача автовладельца", `<p class="profile-description">${item.description}</p><p class="prose">${isGig ? "Работа по готовому регламенту студии. Старший специалист покажет рабочее место, материалы и стандарт сдачи результата." : "Перед началом нужен осмотр и согласование точного объёма. Предложите стоимость, срок и опишите похожий опыт в отклике."}</p>`)}${panel(isGig ? "Требования к исполнителю" : "Что важно учесть", `<ul class="detail-list check-list">${(isGig ? ["Опыт комплексной мойки и уборки салона.", "Готовность к полной смене без опозданий.", "Аккуратная работа с химией и инвентарём.", "Фото результата по стандарту студии."] : ["Оценить состояние автомобиля перед началом.", "Использовать безопасные профильные материалы.", "Показать процесс и итоговый результат.", "Согласовать любые дополнительные работы заранее."]).map((text) => `<li>${text}</li>`).join("")}</ul>`)}${panel(isGig ? "Условия смены" : "Автомобиль и сроки", `<div class="terms-grid">${infoItem("card", isGig ? "Оплата" : "Бюджет", item.salary)}${infoItem("calendar", isGig ? "Дата" : "Желаемый срок", item.schedule)}${infoItem("wrench", isGig ? "Специализация" : "Автомобиль", isGig ? item.tags.join(" · ") : "Toyota RAV4 · 2021")}${infoItem("shield", "Подтверждение", isGig ? "Оплата после закрытия смены" : "Выбор исполнителя после согласования")}</div>`)}${panel("Локация", miniMap(item.city, isGig ? "Shine&Go · Центральный филиал" : "Адрес доступен после подтверждения"))}`;
  const rail = `<section class="detail-action-card"><span class="workspace-kicker">${isGig ? "Свободная смена" : "Открытая заявка"}</span><div class="detail-action-value">${item.salary}</div><p>${isGig ? "Откликнитесь с коротким описанием опыта. Заказчик подтвердит смену в сообщениях." : "Предложите цену и срок. Клиент сможет открыть ваш профиль и примеры работ."}</p>${action}${linkBtn("Написать сообщение", "/messages", { cls: "secondary block mt-1", iconName: "message" })}<small>${icon("shield", "sm")} Не переводите деньги вне платформы</small></section>${panel(isGig ? "Заказчик" : "Автовладелец", `<div class="detail-company">${isGig ? brandAvatar(item.company, "lg") : personAvatar(item.company, "lg")}<div><h3>${item.company}</h3><p>${item.city} · документы проверены</p></div></div><div class="detail-company-stats"><span><b>9,8</b> рейтинг</span><span><b>12</b> заказов</span></div>`)}`;
  return `${detailHeader({ type, item, image: isGig ? "02" : "07", stats: [[item.salary, isGig ? "за смену" : "бюджет"], [item.schedule, isGig ? "длительность" : "срок"], [item.experience, "отклики"]], badges: item.tags, action })}<div class="wrap"><div class="catalog-detail-layout"><main>${content}</main><aside class="catalog-detail-rail">${rail}</aside></div></div>${detailFooter(isGig ? "Откликнуться" : "Предложить услуги")}`;
}

export function catalogDetailPage(ctx, type, id) {
  const source = { vacancies: VACANCIES, gigs: GIGS, orders: ORDERS, promos: PROMOS }[type];
  const item = source.find((entry) => entry.id === id) || source[0];
  if (type === "promos") return promoDetail(item);
  if (type === "vacancies") return vacancyDetail(item);
  return taskDetail(ctx, type, item);
}
